from typing import List
from collections import Counter

class Solution:
    def uncommonFromSentences(self, s1: str, s2: str) -> List[str]:
        count = Counter((s1 + " " + s2).split())
        return [w for w, c in count.items() if c == 1]

class Solution {
public:
    vector<string> uncommonFromSentences(string s1, string s2) {
        unordered_map<string, int> count;
        stringstream ss(s1 + " " + s2);
        string w;
        while (ss >> w) count[w]++;
        vector<string> ans;
        for (auto& [word, cnt] : count) {
            if (cnt == 1) ans.push_back(word);
        }
        return ans;
    }
};

class Solution {
    public String[] uncommonFromSentences(String s1, String s2) {
        Map<String, Integer> count = new HashMap<>();
        for (String w : (s1 + " " + s2).split(" ")) {
            count.put(w, count.getOrDefault(w, 0) + 1);
        }
        List<String> ans = new ArrayList<>();
        for (Map.Entry<String, Integer> e : count.entrySet()) {
            if (e.getValue() == 1) ans.add(e.getKey());
        }
        return ans.toArray(new String[0]);
    }
}

var uncommonFromSentences = function(s1, s2) {
    const count = new Map();
    for (const w of `${s1} ${s2}`.split(' ')) {
        count.set(w, (count.get(w) || 0) + 1);
    }
    const ans = [];
    for (const [w, cnt] of count.entries()) {
        if (cnt === 1) ans.push(w);
    }
    return ans;
};
